namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (principal is null || resource is null || request is null)
            return Deny("missing-context");

        if (TryValidateContext(principal, resource, request, out var rejection))
            return rejection;

        var permissions = GetPermissions(principal, resource, request, delegations);

        if (request.BreakGlass)
            return DecideBreakGlass(request, permissions);

        if (TryApplyResourcePolicy(resource, request, out rejection))
            return rejection;

        if (TryAuthorizeAction(request, permissions, out rejection))
            return rejection;

        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            permissions.Delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || resource.Classification == "restricted");
    }

    private static bool TryValidateContext(
        Principal principal,
        Resource resource,
        AccessRequest request,
        out AccessDecision rejection)
    {
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return Reject("invalid-identity", out rejection);

        if (principal.Suspended)
            return Reject("principal-suspended", out rejection);

        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return Reject("tenant-mismatch", out rejection);

        if (resource.Locked && request.Action != "read")
            return Reject("resource-locked", out rejection);

        if (request.MinuteOfDay is < 0 or > 1439)
            return Reject("invalid-time", out rejection);

        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return Reject("challenge-required", out rejection);

        rejection = default!;
        return false;
    }

    private static AccessPermissions GetPermissions(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        return new AccessPermissions(
            principal.Roles.Contains("administrator"),
            principal.Roles.Contains("operator"),
            principal.Roles.Contains("auditor"),
            principal.Id == resource.OwnerId,
            delegations.HasDelegation(principal.Id, resource.Id, request.Action));
    }

    private static AccessDecision DecideBreakGlass(
        AccessRequest request,
        AccessPermissions permissions)
    {
        return permissions.Administrator && request.StrongAuthentication
            ? new AccessDecision(true, "break-glass", true)
            : Deny("invalid-break-glass");
    }

    private static bool TryApplyResourcePolicy(
        Resource resource,
        AccessRequest request,
        out AccessDecision rejection)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
            return Reject("strong-authentication-required", out rejection);

        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
            return Reject("trusted-network-required", out rejection);

        rejection = default!;
        return false;
    }

    private static bool TryAuthorizeAction(
        AccessRequest request,
        AccessPermissions permissions,
        out AccessDecision rejection)
    {
        if (request.Action == "delete" && !permissions.Administrator)
            return Reject("administrator-required", out rejection);

        if (request.Action == "write" && !permissions.CanWrite)
            return Reject("write-not-authorised", out rejection);

        if (request.Action == "read" && !permissions.CanRead)
        {
            rejection = new AccessDecision(false, "read-not-authorised", false);
            return true;
        }

        if (request.Action is not ("read" or "write" or "delete"))
            return Reject("unknown-action", out rejection);

        rejection = default!;
        return false;
    }

    private static bool Reject(string reason, out AccessDecision rejection)
    {
        rejection = Deny(reason);
        return true;
    }

    private static AccessDecision Deny(string reason) => new(false, reason, true);

    private readonly record struct AccessPermissions(
        bool Administrator,
        bool Operator,
        bool Auditor,
        bool Owner,
        bool Delegated)
    {
        public bool CanWrite => Administrator || Operator || Owner || Delegated;
        public bool CanRead => Administrator || Operator || Auditor || Owner || Delegated;
    }
}
